INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','agreement-advanced','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"agreement-advanced","title":"Agreement with complex subjects","level":"B2","order":58,"summary":"Find the head of a subject phrase and handle indefinite pronouns, quantities and collective nouns carefully.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["The head controls agreement","Indefinite pronouns","Coordinated subjects and quantities","Collective nouns and variation"],"rules":[{"title":"The head controls agreement","explanation":"A subject can contain another noun inside a prepositional phrase. In ordinary agreement, the **head of the subject phrase** controls the verb, not the nearest noun. The box of tools is singular because box is the head.","pattern":"The **list** of names **is** ready.","commonMistakes":["The list of names are ready incorrectly lets the nearby plural names control agreement."],"examples":["“The list of tasks needed to prepare the visitor guide **is** ready.”","“The list of tasks needed to restore the old portrait **is** ready.”"],"skill":"form"},{"title":"Indefinite pronouns","explanation":"Everyone, someone, anybody and each normally take singular verb agreement. They can still be referred back to with singular they. Each of the students is ready combines singular each with a plural noun inside an of phrase.","pattern":"**Everyone is** ready; **they** have a ticket.","commonMistakes":["Singular they does not change the agreement of everyone itself to plural."],"examples":["“Everyone who can prepare the visitor guide **is** welcome.”","“Everyone who can restore the old portrait **is** welcome.”"],"skill":"meaning"},{"title":"Coordinated subjects and quantities","explanation":"Two separate subjects joined by and normally take a plural verb. A combined dish, title or single measured amount can be treated as one unit. Percentages and fractions often take agreement from what is being measured.","pattern":"The guide and the driver **are** here. / Ten pounds **is** enough.","commonMistakes":["Agreement with quantities depends on meaning: ten pounds is a price, but the coins are separate objects."],"examples":["“The guide and the assistant **are** ready to prepare the visitor guide.”","“The guide and the assistant **are** ready to restore the old portrait.”"],"skill":"contrast"},{"title":"Collective nouns and variation","explanation":"A team or committee may take singular agreement when treated as one unit. British English also commonly uses plural agreement when its members are in focus; American English more often favours singular. Keep pronoun choices and viewpoint consistent.","pattern":"The team **is** united. / The team **are** arguing among themselves.","commonMistakes":["Do not label every plural collective agreement wrong without specifying variety and intended meaning."],"examples":["“Each of the people assigned to prepare the visitor guide **has** a copy of the instructions.”","“Each of the people assigned to restore the old portrait **has** a copy of the instructions.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-agreement","dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"850e7792-7f5f-5d88-a245-f1b8cd94ff0c","topicSlug":"agreement-advanced","level":"B2","prompt":"“The list of tasks needed to prepare the visitor guide ____ ready.”","choices":[{"id":"A","text":"be"},{"id":"B","text":"is"},{"id":"C","text":"are"},{"id":"D","text":"am"}],"answerId":"B","hint":"Remove the **of tasks** phrase mentally and find the subject head.","explanation":"The head of the subject is singular **list**. The plural tasks is inside an of phrase.","keywords":["head-agreement"],"skill":"head-agreement","contextKey":"agreement-advanced-1","fingerprint":"42051bf241cd6131fbe63433321fa747ac1727036c0cc246b29566fea1ced59d","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-agreement"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Remove the **of tasks** phrase mentally and find the subject head.","The head of the subject is singular **list**. The plural tasks is inside an of phrase.","Choose **is**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Be is not the required finite present form.","B":"The head of the subject is singular **list**. The plural tasks is inside an of phrase.","C":"This agrees with nearby tasks rather than the subject head list.","D":"Am agrees only with I."}}},{"id":"030b1a08-6117-509f-a3d4-585d03f7bbd0","topicSlug":"agreement-advanced","level":"B2","prompt":"“Everyone who can prepare the visitor guide ____ welcome.”","choices":[{"id":"A","text":"be"},{"id":"B","text":"is"},{"id":"C","text":"are"},{"id":"D","text":"am"}],"answerId":"B","hint":"The subject head is **everyone**, which takes singular agreement.","explanation":"**Everyone** takes singular verb agreement, even though it includes many people.","keywords":["indefinite-agreement"],"skill":"indefinite-agreement","contextKey":"agreement-advanced-1","fingerprint":"b2e0f9096477f6b2b0a40a2ca2354458da9d61d225a780ac5fff9ca74d269be3","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-agreement"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The subject head is **everyone**, which takes singular agreement.","**Everyone** takes singular verb agreement, even though it includes many people.","Choose **is**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Be is not a finite present form here.","B":"**Everyone** takes singular verb agreement, even though it includes many people.","C":"Everyone is grammatically singular in this construction.","D":"Am agrees with I."}}},{"id":"75c7b839-7f2d-5392-a698-261246a51b3e","topicSlug":"agreement-advanced","level":"B2","prompt":"“The guide and the assistant ____ ready to prepare the visitor guide.”","choices":[{"id":"A","text":"be"},{"id":"B","text":"are"},{"id":"C","text":"is"},{"id":"D","text":"am"}],"answerId":"B","hint":"Count the two distinct subjects joined by **and**.","explanation":"Two distinct people joined by **and** form a plural subject.","keywords":["coordinated-subjects"],"skill":"coordinated-subjects","contextKey":"agreement-advanced-1","fingerprint":"0c96f82b016a7d9a273d28f0e3c30d0e0a10f7d44bca5f1c6e97200570a53db2","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-agreement"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Count the two distinct subjects joined by **and**.","Two distinct people joined by **and** form a plural subject.","Choose **are**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Be is not the finite present form.","B":"Two distinct people joined by **and** form a plural subject.","C":"The subject names two separate people, not one unit.","D":"Am agrees with I."}}},{"id":"05ca8cee-763f-55b5-abe9-3f651693914d","topicSlug":"agreement-advanced","level":"B2","prompt":"“Each of the people assigned to prepare the visitor guide ____ a copy of the instructions.”","choices":[{"id":"A","text":"has"},{"id":"B","text":"have"},{"id":"C","text":"having"},{"id":"D","text":"to have"}],"answerId":"A","hint":"The phrase **each of** selects members individually and takes a singular verb.","explanation":"The subject head **each** is singular, so use **has**.","keywords":["each-of-agreement"],"skill":"each-of-agreement","contextKey":"agreement-advanced-1","fingerprint":"4fa94bb73705cb2c1a17ba3443157092747676e8e633fad46a3540580c512fe6","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-agreement"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The phrase **each of** selects members individually and takes a singular verb.","The subject head **each** is singular, so use **has**.","Choose **has**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The subject head **each** is singular, so use **has**.","B":"The plural people is inside an of phrase; each controls agreement.","C":"Having alone is not a finite verb.","D":"An infinitive cannot be the finite predicate here."}}},{"id":"37f5878e-1b1f-5496-ad19-455a694cc3cb","topicSlug":"agreement-advanced","level":"B2","prompt":"“The list of tasks needed to restore the old portrait ____ ready.”","choices":[{"id":"A","text":"is"},{"id":"B","text":"are"},{"id":"C","text":"am"},{"id":"D","text":"be"}],"answerId":"A","hint":"Remove the **of tasks** phrase mentally and find the subject head.","explanation":"The head of the subject is singular **list**. The plural tasks is inside an of phrase.","keywords":["head-agreement"],"skill":"head-agreement","contextKey":"agreement-advanced-2","fingerprint":"6dda2197f0012d0f326b8a57359f66730f18b4dc9aacaf5eba8bdc11392de30f","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-agreement"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Remove the **of tasks** phrase mentally and find the subject head.","The head of the subject is singular **list**. The plural tasks is inside an of phrase.","Choose **is**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The head of the subj